48:     if (audioContext.state === 'suspended') audioContext.resume();
49:     const osc = audioContext.createOscillator();
50:     const gain = audioContext.createGain();
51:     osc.type = type;
52:     osc.frequency.setValueAtTime(freq, audioContext.currentTime);
53:     gain.gain.setValueAtTime(volume, audioContext.currentTime);
54:     gain.gain.exponentialRampToValueAtTime(.001, audioContext.currentTime + duration);
55:     osc.connect(gain).connect(audioContext.destination);
56:     osc.start(); osc.stop(audioContext.currentTime + duration);
