184: function movePlayer(p, x, z, dt) {
185:   const u = p.userData;
186:   if (u.block || (u.attack > 0 && u.attackType !== 'dodge')) return;
187:   const length = Math.hypot(x, z) || 1;
188:   const speed = u.data.stats[1] / 65 * (u.dodge > 0 ? 1.8 : 1);
189:   p.position.x = THREE.MathUtils.clamp(p.position.x + (x / length) * speed * dt, -5.8, 5.8);
190:   p.position.z = THREE.MathUtils.clamp(p.position.z + (z / length) * speed * dt, -3.4, 3.4);
