192: function doHit(attacker, defender) {
193:   const u = attacker.userData, v = defender.userData;
194:   if (!u.attackType || u.hitLanded || u.attack <= 0 || u.attackType === 'dodge') return;
195:   const active = u.attackDuration - u.attack;
196:   if (active < .08 || active > (u.attackType === 'special' ? .4 : .22)) return;
197:   const dx = defender.position.x - attacker.position.x;
198:   const dz = defender.position.z - attacker.position.z;
199:   const inRange = Math.hypot(dx, dz) < (u.attackType === 'kick' ? 2 : 1.65);
200:   const facing = (u.side === -1 && dx > 0) || (u.side === 1 && dx < 0);
201:   if (!inRange || !facing) return;
202:   u.hitLanded = true;
203:   const peaceful = u.data.peaceful;
204:   const base = u.attackType === 'special' ? 20 : u.attackType === 'kick' ? 12 : 8;
205:   const damage = base * (u.data.stats[0] / 75) * (v.block ? .2 : 1) * (v.dodge > 0 ? 0 : 1);
206:   v.health = Math.max(0, v.health - damage);
207:   v.hit = .2;
208:   u.meter = Math.min(100, u.meter + (u.attackType === 'special' ? 0 : 17));
209:   v.meter = Math.min(100, v.meter + (v.block ? 9 : 6));
210:   updateHealth();
211:   if (v.dodge <= 0) tone(v.block ? 105 : peaceful ? 500 : 90, .13, peaceful ? 'sine' : 'square', .035);
212:   if (peaceful) byId('fight-message').textContent = u.attackType === 'special' ? 'A PEACEFUL APPEAL — THE CROWD IS LISTENING' : 'A GENTLE PERSUASION — NOT A PUNCH';
213:   else byId('fight-message').textContent = v.block ? 'GUARD HELD — MOMENTUM BUILT' : u.attackType === 'special' ? 'SPECIAL MOVE CONNECTS!' : 'NICE HIT!';
214:   if (mode !== 'training' && v.health <= 0) endFight(attacker);
215: }
216: function cpuThink(p, opponent, dt) {
217:   const u = p.userData, v = opponent.userData;
218:   u.ai -= dt;
219:   const dx = opponent.position.x - p.position.x;
220:   const dz = opponent.position.z - p.position.z;
221:   const distance = Math.hypot(dx, dz);
222:   if (u.ai <= 0) {
223:     u.ai = .24 + Math.random() * .28;
224:     if (distance < 1.65 && Math.random() < .32) {
225:       if (v.attack > 0 && Math.random() < .5) setBlock(p, true);
226:       else attack(p, Math.random() < .16 && u.meter >= 40 ? 'special' : Math.random() < .48 ? 'kick' : 'punch');
227:     } else if (distance < 1.2 && Math.random() < .12) attack(p, 'dodge');
228:     else setBlock(p, false);
229:   }
230:   if (distance > 1.15 && !u.block) movePlayer(p, Math.sign(dx), dz / Math.max(1, Math.abs(dz)), dt);
231:   else if (distance < 1.1 && Math.random() < .01) movePlayer(p, Math.sign(dx), Math.sign(dz), dt);
232: }
233: function animateFighter(p, dt, t) {
234:   const u = p.userData, parts = u.parts;
235:   u.cool = Math.max(0, u.cool - dt);
236:   u.attack = Math.max(0, u.attack - dt);
237:   u.dodge = Math.max(0, u.dodge - dt);
238:   u.hit = Math.max(0, u.hit - dt);
239:   u.stamina = Math.min(100, u.stamina + dt * 11);
240:   const walking = Math.abs(u.moveX || 0) + Math.abs(u.moveZ || 0);
241:   parts.body.position.y = Math.sin(t * 8 + u.side) * .035 * walking;
242:   if (u.attack > 0 && u.attackType === 'punch') parts.arms[1].rotation.x = -.9;
243:   else if (u.attack > 0 && u.attackType === 'kick') parts.legs[1].rotation.x = -.95;
244:   else if (!u.block) {
245:     parts.arms.forEach((arm) => { arm.rotation.x = THREE.MathUtils.damp(arm.rotation.x, Math.sin(t * 2 + u.side) * .045, 7, dt); });
246:     parts.legs.forEach((leg) => { leg.rotation.x = THREE.MathUtils.damp(leg.rotation.x, walking ? Math.sin(t * 8 + u.side) * .3 : 0, 8, dt); });
247:   }
248:   parts.body.rotation.z = THREE.MathUtils.damp(parts.body.rotation.z, u.hit > 0 ? .16 * u.side : 0, 7, dt);
249:   if (u.dodge > 0) parts.body.rotation.z = u.side * .45;
250:   if (!u.block) parts.body.rotation.x = THREE.MathUtils.damp(parts.body.rotation.x, 0, 7, dt);
251:   p.rotation.y = u.side === -1 ? 0 : Math.PI;
252: }
