362: function frame(now) {
363:   requestAnimationFrame(frame);
364:   const dt = Math.min(.04, (now - lastTime) / 1000 || 0);
365:   lastTime = now;
366:   const t = now / 1000;
367:   if (running && !paused) {
368:     elapsed += dt;
369:     if (mode !== 'training') {
370:       const seconds = Math.max(0, 60 - Math.floor(elapsed));
371:       byId('timer').textContent = String(seconds).padStart(2, '0');
372:       if (seconds === 0) endFight(players[0].userData.health >= players[1].userData.health ? players[0] : players[1]);
373:     }
374:     for (let i = 0; i < players.length; i++) {
375:       const player = players[i], u = player.userData, foe = players[1 - i];
376:       u.moveX = 0; u.moveZ = 0;
377:       if (i === 0) {
378:         const x = (keys.KeyD ? 1 : 0) - (keys.KeyA ? 1 : 0) + touchMove.x;
379:         const z = (keys.KeyS ? 1 : 0) - (keys.KeyW ? 1 : 0) + touchMove.z;
380:         if (x || z) { u.moveX = x; u.moveZ = z; movePlayer(player, x, z, dt); }
381:       } else if (mode === 'local') {
